'use strict';
// Expériences de pensée pour WikiFeed – version française de thoughts.js.
// Mêmes ids, même ordre, mêmes positions de réponse que le fichier allemand, pour que les réponses passent d’une langue à l’autre.

const THINK_FIELDS_FR = {
  ethik: { label: 'Éthique et morale', axis: ['Les conséquences comptent', 'Les principes comptent'] },
  geist: { label: 'Conscience et esprit', axis: ['L’esprit est physique', 'La conscience est plus'] },
  ich: { label: 'Identité et moi', axis: ['Matière et origine comptent', 'Forme et mémoire comptent'] },
  physik: { label: 'Physique' },
  logik: { label: 'Logique et mathématiques' },
  wahl: { label: 'Décisions et théorie des jeux' },
  wissen: { label: 'Connaissance et réalité' },
};

const THOUGHTS_FR = [
  // ---------------- Éthique et morale ----------------
  { id: 'trolley', icon: 'scale', field: 'ethik', title: 'Le dilemme du tramway', wiki: 'Dilemme du tramway',
    text: 'Un tramway fou fonce sur cinq ouvriers qui travaillent sur la voie. Tu te trouves à côté d’un aiguillage. Si tu actionnes le levier, le tram part sur une voie de garage – mais un ouvrier seul s’y trouve, et il mourra.',
    q: 'Tu actionnes le levier ?',
    opts: [['Oui, je l’actionne', -1], ['Non, je ne m’en mêle pas', 1]],
    args: [['Pour', 'Cinq vies pèsent plus qu’une. Ne rien faire, c’est aussi décider – simplement choisir le pire résultat.'],
      ['Contre', 'Laisser mourir et tuer, ce n’est pas la même chose. Sans toi, cet ouvrier n’aurait jamais été en danger, et tu n’as pas le droit de le traiter comme un chiffre dans une addition.']],
    twist: { text: 'Nouvelle situation : tu es sur un pont au-dessus de la voie. À côté de toi se tient un homme très corpulent. Si tu le pousses, son corps arrête le tram – il meurt, les cinq survivent.',
      q: 'Tu le pousses ?', opts: [['Oui', -1], ['Non', 1]],
      note: 'Les chiffres sont les mêmes : un contre cinq. Pourtant, la plupart des gens hésitent bien plus ici. C’est cet écart entre le calcul et le ressenti qui a rendu le problème célèbre.' },
    info: 'La version de l’aiguillage vient de la philosophe britannique Philippa Foot (1967), celle du pont de Judith Jarvis Thomson. Aujourd’hui, la question revient dans le débat sur la façon dont une voiture autonome doit décider en cas d’accident inévitable.' },

  { id: 'teich', icon: 'scale', field: 'ethik', title: 'L’enfant dans l’étang', wiki: 'Peter Singer',
    text: 'En allant au travail, tu vois un petit enfant sur le point de se noyer dans un étang peu profond. Tu pourrais facilement le sauver, mais tes chaussures neuves, qui t’ont coûté cher, seraient fichues. Il n’y a personne d’autre.',
    q: 'Es-tu obligé d’y aller ?',
    opts: ['Oui, évidemment', 'Non, c’est facultatif'],
    args: [['Le vrai enjeu', 'Presque tout le monde répond : évidemment. Une paire de chaussures n’est rien face à une vie. Le philosophe Peter Singer en conclut : alors tu dois aussi donner quand la même somme peut sauver un enfant à l’autre bout du monde.'],
      ['L’objection', 'La proximité change les choses. À l’étang, il n’y a que toi ; pour un don, des millions de gens pourraient aider. Et un devoir sans fin en demande trop à n’importe qui.']],
    twist: { text: 'L’enfant n’est pas devant toi, mais à 6 000 kilomètres. Le prix de tes chaussures suffirait à le protéger d’une maladie mortelle.',
      q: 'Es-tu tout aussi obligé ?', opts: ['Oui, la distance ne change rien', 'Non, ce n’est pas pareil'],
      note: 'Pour Singer, la distance ne compte pas moralement. Qui n’est pas d’accord doit expliquer pourquoi des kilomètres rendraient une vie moins précieuse.' },
    info: 'L’exemple vient de l’essai de Peter Singer « Famine, Affluence, and Morality » (1972). C’est l’un des textes les plus influents de l’éthique moderne et l’un des points de départ du mouvement de « l’altruisme efficace ».' },

  { id: 'schleier', icon: 'scale', field: 'ethik', title: 'Le voile d’ignorance', wiki: 'Position originelle',
    text: 'Tu dois fixer les règles d’une nouvelle société : impôts, salaires, droits. Le hic : tu ne sais pas qui tu y seras. Riche ou pauvre, en bonne santé ou malade, doué ou non – ce sera tiré au sort après coup.',
    q: 'Quelle société choisis-tu ?',
    opts: ['Celle où les plus pauvres vivent le mieux possible', 'Celle qui a la moyenne la plus élevée, même si certains ont peu', 'Celle des grandes chances de gagner et des grands risques'],
    args: [['La réponse de Rawls', 'Quand tu ne sais pas où tu atterriras, tu te protèges contre le pire. Une inégalité n’est juste que si elle profite aussi aux plus faibles.'],
      ['L’objection', 'Cela suppose que tout le monde soit extrêmement prudent. Qui aime un peu le risque choisira la moyenne la plus élevée – et retombe sur l’utilitarisme.']],
    info: 'Le philosophe américain John Rawls a introduit cette expérience de pensée dans « Théorie de la justice » (1971). L’idée : des règles équitables sont celles que tu accepterais avant de connaître ta propre situation.' },

  { id: 'gyges', icon: 'scale', field: 'ethik', title: 'L’anneau de Gygès', wiki: 'Anneau de Gygès',
    text: 'Un berger trouve un anneau qui le rend invisible dès qu’il le tourne. Personne ne pourra jamais le prendre sur le fait. Il séduit la reine, tue le roi et s’empare du pouvoir.',
    q: 'Resterais-tu juste avec un tel anneau ?',
    opts: ['Oui, je resterais honnête', 'Non, tôt ou tard, je craquerais', 'Au début oui, à la longue je ne sais pas'],
    args: [['La thèse de Glaucon', 'Personne n’est juste par choix. Nous suivons les règles par peur de la punition et de la mauvaise réputation. Enlève cela, et le juste agit comme l’injuste.'],
      ['La réponse de Platon', 'Celui qui fait le mal se nuit à lui-même : son âme tombe dans le désordre et il devient esclave de ses désirs. La justice paie, même quand personne ne regarde.']],
    info: 'Glaucon raconte l’histoire au livre II de « La République » de Platon (vers 375 av. J.-C.). Elle demande si la morale est plus que la peur de se faire prendre – et elle colle à tout ce que les gens font anonymement sur Internet.' },

  { id: 'karneades', icon: 'scale', field: 'ethik', title: 'La planche de Carnéade', wiki: 'Carnéade',
    text: 'Deux naufragés dérivent en pleine mer. Il n’y a qu’une planche, et elle ne porte qu’une personne. L’un l’atteint le premier. L’autre le pousse, se sauve, et le premier se noie.',
    q: 'Le second a-t-il mal agi ?',
    opts: ['Oui, c’est un meurtre', 'Non, en danger de mort, ça ne compte pas', 'Mal, oui, mais pas punissable'],
    args: [['Cela reste mal', 'Le premier n’avait rien fait de mal. Sa vie valait tout autant, et personne n’a le droit de tuer un innocent pour se sauver.'],
      ['On ne peut pas exiger plus', 'Aucune loi ne peut exiger qu’on meure volontairement. Celui qui se bat pour sa vie n’agit pas librement, mais par pure nécessité.']],
    info: 'L’exemple est attribué au philosophe grec Carnéade (IIe siècle av. J.-C.). Le droit pénal allemand suit la troisième réponse : l’acte est illicite, mais peut rester impuni au titre de l’« état de nécessité excusant ».' },

  { id: 'omelas', icon: 'scale', field: 'ethik', title: 'La ville d’Omelas', wiki: 'Ceux qui partent d\'Omelas',
    text: 'Omelas est une ville parfaitement heureuse : pas de guerre, pas de pauvreté, tout le monde est en bonne santé et satisfait. Mais ce bonheur dépend d’une condition. Dans une cave, un seul enfant doit vivre dans la misère. Si on le libère, le bonheur de tous prend fin.',
    q: 'Que fais-tu quand tu l’apprends ?',
    opts: [['Je reste – le bonheur de tant de gens pèse plus lourd', -1], ['Je pars', 1], ['Je libère l’enfant', 1]],
    args: [['Pour rester', 'Des milliers de gens vivent heureux, un seul souffre. Tout autre monde serait pire au total. Notre propre prospérité repose elle aussi sur la souffrance des autres.'],
      ['Contre', 'Un bonheur bâti sur le supplice d’un innocent ne vaut rien. Certaines choses ne se font pas, quel que soit le bénéfice qu’on en tire.']],
    info: 'Ursula K. Le Guin a écrit la nouvelle « Ceux qui partent d’Omelas » en 1973. Elle passe pour l’une des critiques les plus acérées de l’utilitarisme, qui juge les actes uniquement à la somme de bonheur qu’ils produisent.' },

  { id: 'luege', icon: 'scale', field: 'ethik', title: 'L’assassin à la porte', wiki: 'D\'un prétendu droit de mentir par humanité',
    text: 'Ton ami fuit un assassin et se cache chez toi. Peu après, l’assassin frappe et te demande si ton ami est chez toi. Te taire n’est pas possible – tu dois répondre.',
    q: 'As-tu le droit de mentir ?',
    opts: [['Oui, évidemment', -1], ['Non, mentir est toujours mal', 1]],
    args: [['Pour le mensonge', 'Ici, la vérité aide un assassin. Une règle qui mène à un tel résultat ne peut pas être juste. L’assassin n’a aucun droit à ta franchise.'],
      ['La réponse de Kant', 'Celui qui ment devient responsable de tout ce qui s’ensuit. Surtout : si mentir est permis dès que cela semble utile, plus personne ne peut se fier à la parole de quiconque.']],
    info: 'Emmanuel Kant a vraiment défendu l’interdiction stricte du mensonge en 1797, en réponse au Français Benjamin Constant. Rares sont ses thèses aussi vivement critiquées aujourd’hui encore, y compris par des kantiens.' },

  // ---------------- Conscience et esprit ----------------
  { id: 'mary', icon: 'eye', field: 'geist', title: 'La chambre de Mary', wiki: 'Argument de la connaissance',
    text: 'Mary est la meilleure spécialiste des couleurs au monde. Elle sait tout ce que la physique et les neurosciences peuvent dire des couleurs. Mais elle a passé toute sa vie dans une pièce en noir et blanc et n’a jamais vu une couleur. Un jour, elle sort et voit une tomate rouge.',
    q: 'Mary apprend-elle quelque chose de nouveau à cet instant ?',
    opts: [['Oui – à quoi ressemble le rouge', 1], ['Non, elle savait déjà tout', -1]],
    args: [['Oui', 'Elle découvre ce que ça fait de voir du rouge. Ce n’était dans aucun livre. Il existe donc des faits sur le vécu que la physique ne saisit pas.'],
      ['Non', 'Mary n’acquiert pas un savoir nouveau, mais une capacité nouvelle : reconnaître et se représenter le rouge. Ou bien elle découvre simplement un fait ancien sous un nouvel angle.']],
    info: 'Le philosophe australien Frank Jackson a publié cette expérience de pensée en 1982 comme argument contre le physicalisme. Plus tard, il a lui-même changé de camp et tient aujourd’hui son propre argument pour erroné.' },

  { id: 'china', icon: 'eye', field: 'geist', title: 'La chambre chinoise', wiki: 'Chambre chinoise',
    text: 'Tu es assis dans une pièce fermée et tu ne parles pas un mot de chinois. Des papiers couverts de caractères chinois arrivent par une fente. À l’aide d’un épais manuel de règles (« à ces caractères, réponds par ceux-là »), tu rédiges des réponses. Dehors, les gens sont convaincus de parler avec quelqu’un qui maîtrise le chinois.',
    q: 'Est-ce que quelqu’un ici comprend le chinois ?',
    opts: [['Non, personne', 1], ['Oui – le système entier : pièce, manuel et personne', -1]],
    args: [['L’argument de Searle', 'Tu ne fais que manipuler des symboles selon des règles, sans savoir ce qu’ils signifient. C’est exactement ce que fait un ordinateur. Suivre des règles, ce n’est pas encore comprendre.'],
      ['La réponse du système', 'Tu n’es qu’un rouage, comme un neurone isolé ne comprend pas le français. La compréhension se trouve dans le système tout entier, pas en toi.']],
    info: 'John Searle a avancé l’argument en 1980 contre l’idée qu’un ordinateur bien programmé ait un esprit. Depuis qu’il existe des modèles de langage qui répondent avec aisance, on en débat aussi vivement qu’au premier jour.' },

  { id: 'zombie', icon: 'eye', field: 'geist', title: 'Le zombie philosophique', wiki: 'Zombie philosophique',
    text: 'Imagine un être identique à toi, atome pour atome. Il parle, rit et crie « aïe ! » quand il se cogne. Mais à l’intérieur, tout est noir : il ne vit rien, ne ressent rien, il n’y a personne.',
    q: 'Un tel être est-il seulement concevable ?',
    opts: [['Oui, on peut l’imaginer', 1], ['Non, c’est une contradiction', -1]],
    args: [['Oui', 'S’il est concevable, alors le vécu ne découle pas nécessairement du corps. La conscience serait quelque chose en plus, que la physique seule n’explique pas.'],
      ['Non', 'Nous croyons seulement pouvoir l’imaginer. Un être doté exactement de ton cerveau affirmerait lui aussi être conscient – pour les mêmes raisons que toi.']],
    info: 'L’idée a été rendue célèbre par le philosophe australien David Chalmers dans les années 1990. Elle fait partie de son « problème difficile de la conscience » : pourquoi le traitement de l’information s’accompagne-t-il d’un ressenti ?' },

  { id: 'fledermaus', icon: 'eye', field: 'geist', title: 'Quel effet cela fait-il d’être une chauve-souris ?', wiki: 'Quel effet cela fait, d\'être une chauve-souris ?',
    text: 'Les chauves-souris s’orientent par écholocation : elles poussent des cris et « voient » grâce à l’écho. Suppose que la science sache un jour tout de leur cerveau, chaque cellule et chaque circuit.',
    q: 'Saurions-nous alors ce que ça fait d’être une chauve-souris ?',
    opts: [['Non, cela nous reste fermé', 1], ['Oui, en principe', -1]],
    args: [['Non', 'La science décrit de l’extérieur. Le vécu n’existe que de l’intérieur. Au mieux, nous pouvons imaginer ce que ce serait pour nous d’être suspendus au plafond – pas ce que c’est pour la chauve-souris.'],
      ['Oui', 'On a aussi cru autrefois que les couleurs ou la chaleur étaient inexplicables. Avec assez de connaissances, le vécu pourrait peut-être être reconstruit ou traduit dans le nôtre.']],
    info: 'L’essai de Thomas Nagel « Quel effet cela fait-il d’être une chauve-souris ? » (1974) est l’un des textes les plus cités de la philosophie de l’esprit. Nagel a choisi les chauves-souris parce qu’elles sont assez proches de nous pour avoir un vécu, et assez étrangères pour que nous ne le connaissions pas.' },

  { id: 'spektrum', icon: 'eye', field: 'geist', title: 'Le spectre inversé', wiki: 'Spectre inversé',
    text: 'Peut-être que tu vois intérieurement du rouge là où je vois du vert. Nous aurions tous les deux appris à dire que les tomates sont « rouges » et l’herbe « verte », et nous nous comporterions de la même façon à chaque test. La différence serait uniquement dans le vécu.',
    q: 'Quelqu’un pourrait-il jamais s’en apercevoir ?',
    opts: ['Non, jamais', 'Oui, grâce au cerveau', 'La question n’a pas de sens'],
    args: [['Non', 'Chaque test ne vérifie que le comportement et les mots. Le vécu intérieur lui-même ne peut pas être posé côte à côte et comparé.'],
      ['Oui', 'Les couleurs ont des relations entre elles : le rouge paraît chaud, le jaune est clair, on distingue plus de nuances de rouge que de jaune. Une inversion se trahirait dans ces relations.']],
    info: 'L’idée se trouve déjà chez John Locke en 1690. Aujourd’hui encore, elle sert de pierre de touche à toute théorie qui veut expliquer la conscience par la seule fonction et le seul comportement.' },

  { id: 'turing', icon: 'eye', field: 'geist', title: 'Le test de Turing', wiki: 'Test de Turing',
    text: 'Tu discutes par écrit pendant cinq minutes avec deux inconnus. L’un est un humain, l’autre une machine. À la fin, malgré tous tes efforts, tu es incapable de dire qui est qui.',
    q: 'Cette machine peut-elle penser ?',
    opts: [['Oui, alors elle pense', -1], ['Non, elle fait semblant', 1]],
    args: [['Oui', 'Chez les humains aussi, nous ne déduisons l’esprit qu’à partir du comportement. Exiger plus de la machine, c’est appliquer deux poids, deux mesures.'],
      ['Non', 'Tromper n’est pas penser. Un programme peut produire des réponses sans rien comprendre ni rien vivre – voir la chambre chinoise.']],
    info: 'Alan Turing a proposé le « jeu de l’imitation » en 1950 pour remplacer la vague question « Les machines peuvent-elles penser ? » par un test. Les modèles de langage actuels réussissent souvent ce genre de test – et ce que cela signifie fait débat.' },

  // ---------------- Identité et moi ----------------
  { id: 'theseus', icon: 'loop', field: 'ich', title: 'Le bateau de Thésée', wiki: 'Bateau de Thésée',
    text: 'Les Athéniens conservent au port le bateau du héros Thésée. Chaque année, ils remplacent une planche pourrie par une neuve. Au bout de nombreuses années, il ne reste plus une seule pièce du bateau d’origine.',
    q: 'Est-ce encore le bateau de Thésée ?',
    opts: [['Oui, c’est le même bateau', 1], ['Non, c’est une réplique', -1], 'À partir d’une certaine planche, ce ne l’est plus'],
    args: [['Oui', 'La forme, la fonction et une histoire ininterrompue sont conservées. Un fleuve reste lui aussi le même, alors que de l’eau nouvelle y coule sans cesse.'],
      ['Non', 'Une chose, c’est sa matière. S’il ne reste rien de l’original, tu as une copie, même si elle se trouve au même endroit.']],
    twist: { text: 'Quelqu’un a récupéré en secret toutes les vieilles planches et a reconstruit un bateau avec, dans un chantier naval. Maintenant, il y en a deux.',
      q: 'Lequel est le vrai ?', opts: [['Celui du port', 1], ['Celui fait des vieilles planches', -1], 'Les deux, ou aucun'],
      note: 'Cette version plus pointue vient de Thomas Hobbes. Elle montre que « le même » peut vouloir dire deux choses : la même matière ou la même histoire continue.' },
    info: 'L’énigme nous a été transmise par l’écrivain grec Plutarque. Elle te concerne aussi : la plupart des cellules de ton corps se renouvellent au fil des années. Es-tu encore la même personne que dans ton enfance ?' },

  { id: 'teleporter', icon: 'self', field: 'ich', title: 'Le téléporteur', wiki: 'Paradoxe de la téléportation',
    text: 'Une machine scanne ton corps jusqu’au dernier atome et le détruit au passage. Les données partent sur Mars, où une copie exacte est construite avec de la matière neuve. Elle a tous tes souvenirs et se sent comme toi.',
    q: 'Tu montes dedans ?',
    opts: [['Oui, c’est moi sur Mars', 1], ['Non, je meurs et quelqu’un d’autre continue', -1]],
    args: [['Monter', 'Ce qui fait que tu es toi, ce sont tes souvenirs, ton caractère, tes projets. Tout cela arrive à destination. Il n’y a rien de plus de « toi » à sauver.'],
      ['Ne pas monter', 'Pour toi, c’est le noir. Que quelqu’un se réveille ensuite avec tes souvenirs ne t’aide pas – pas plus qu’un jumeau.']],
    twist: { text: 'La machine a un défaut : ton corps sur Terre n’est pas détruit. Maintenant, il y a deux toi.',
      q: 'Lequel des deux es-tu ?', opts: ['Celui sur Terre', 'Les deux', 'La question n’a pas de réponse'],
      note: 'Derek Parfit en a tiré une conclusion radicale : la question « Est-ce encore moi ? » compte moins qu’on ne le croit. Ce qui importe, c’est que quelqu’un avec mes souvenirs et mes buts continue à vivre.' },
    info: 'L’expérience de pensée apparaît dans le livre de Derek Parfit « Reasons and Persons » (1984). Parfit a écrit que cette idée lui avait ôté une bonne partie de sa peur de la mort.' },

  { id: 'sumpfmann', icon: 'self', field: 'ich', title: 'L’homme des marais', wiki: 'Donald Davidson',
    text: 'Un homme traverse un marais et meurt frappé par la foudre. Au même instant, un second éclair forme par pur hasard une copie exacte de lui à partir de la matière du marais. Elle rentre chez lui, salue sa famille et continue d’écrire son livre.',
    q: 'L’homme des marais est-il la même personne ?',
    opts: [['Oui, il est identique en tout', 1], ['Non, il lui manque le passé', -1]],
    args: [['Oui', 'Personne, pas même lui, ne peut constater de différence. Une différence qui ne change rien n’en est pas une.'],
      ['Non', 'Il « se souvient » de choses qu’il n’a jamais vécues. Il ne reconnaît pas ses amis, puisqu’il ne les a jamais vus. Ses pensées n’ont aucune histoire à laquelle se rapporter.']],
    info: 'Le philosophe américain Donald Davidson a inventé l’homme des marais en 1987. Il voulait montrer que le sens de nos pensées dépend de la manière dont nous les avons acquises au cours de notre vie.' },

  // ---------------- Physique ----------------
  { id: 'maxwell', icon: 'key', field: 'physik', title: 'Le démon de Maxwell', wiki: 'Démon de Maxwell',
    text: 'Une boîte remplie de gaz est séparée par une paroi. Dans la paroi, il y a un minuscule clapet gardé par un démon. Il ne laisse passer les particules rapides que vers la droite et les lentes que vers la gauche. Bientôt, il fait chaud à droite et froid à gauche, sans qu’aucun travail n’ait été fourni.',
    q: 'Le démon peut-il ainsi déjouer les lois de la nature ?',
    opts: ['Oui, en principe', 'Non, il le paie quelque part'],
    correct: 1,
    args: [['Pourquoi c’est tentant', 'On pourrait tirer de l’énergie de la différence de température – un mouvement perpétuel. Cela contredirait le deuxième principe de la thermodynamique, selon lequel le désordre ne diminue jamais de lui-même.'],
      ['La solution', 'Le démon doit retenir la vitesse de chaque particule. Tôt ou tard, sa mémoire est pleine et il doit l’effacer. Or effacer de l’information produit forcément de la chaleur – au moins autant qu’il en a économisé avant.']],
    info: 'James Clerk Maxwell a inventé le démon en 1867. La solution a pris plus de cent ans (Szilárd 1929, Landauer 1961, Bennett 1982) et a révélé quelque chose de profond : l’information est physique.' },

  { id: 'katze', icon: 'atom', field: 'physik', title: 'Le chat de Schrödinger', wiki: 'Chat de Schrödinger',
    text: 'Un chat est enfermé dans une boîte scellée. À l’intérieur se trouve un seul atome radioactif. S’il se désintègre, il déclenche un mécanisme qui libère du poison. D’après les règles de la physique quantique, au bout d’une heure, l’atome est dans une superposition : à la fois désintégré et non désintégré.',
    q: 'Qu’en est-il du chat avant que quelqu’un regarde ?',
    opts: ['Mort et vivant à la fois', 'Soit mort, soit vivant, on ne le sait juste pas', 'Les deux – dans des mondes séparés'],
    args: [['L’intention de Schrödinger', 'Il voulait montrer à quel point cela devient absurde quand on applique telles quelles les règles quantiques aux grands objets. Pour lui, un chat à moitié mort était une absurdité.'],
      ['La vision actuelle', 'Le chat n’est jamais vraiment isolé : l’air, la chaleur et la boîte elle-même « mesurent » en permanence. La superposition disparaît donc en une infime fraction de seconde. C’est ce qu’on appelle la décohérence.']],
    twist: { text: 'Un ami ouvre la boîte et regarde – mais il se trouve lui-même dans un laboratoire scellé, et toi, tu attends devant la porte.',
      q: 'Pour toi, ton ami est-il maintenant dans une superposition ?', opts: ['Oui, tant que je n’ouvre pas la porte', 'Non, son regard a tranché'],
      note: 'C’est « l’ami de Wigner » (1961). Il pose la question gênante de savoir ce qu’est vraiment une mesure et si elle nécessite une conscience. Il n’y a toujours pas de consensus.' },
    info: 'Erwin Schrödinger a décrit cette expérience de pensée en 1935. Quelle interprétation de la physique quantique est la bonne – Copenhague, mondes multiples ou une autre – reste une question ouverte. Les calculs sont les mêmes pour toutes.' },

  { id: 'zwillinge', icon: 'key', field: 'physik', title: 'Le paradoxe des jumeaux', wiki: 'Paradoxe des jumeaux',
    text: 'Anna et Ben sont jumeaux. Anna part presque à la vitesse de la lumière vers une étoile lointaine, puis revient. Ben reste sur Terre. D’après la relativité, le temps s’écoule plus lentement pour les horloges en mouvement. Mais du point de vue d’Anna, c’est Ben qui a bougé.',
    q: 'Qui est le plus jeune quand ils se retrouvent ?',
    opts: ['Anna, la voyageuse', 'Ben, resté à la maison', 'Ils ont le même âge'],
    correct: 0,
    args: [['L’explication', 'La situation n’est pas symétrique. Anna doit faire demi-tour à l’étoile, donc freiner puis accélérer à nouveau. Elle change de référentiel, Ben non. C’est donc clairement pour elle que le moins de temps s’est écoulé.'],
      ['Est-ce qu’on l’a mesuré ?', 'Oui. Des horloges atomiques embarquées dans des avions affichent après l’atterrissage un écart mesurable avec celles restées au sol. Le GPS, lui aussi, se tromperait de plusieurs kilomètres en peu de temps sans ces corrections.']],
    info: 'L’énigme remonte à la relativité restreinte d’Einstein (1905) ; les jumeaux ont été introduits par Paul Langevin en 1911. Ce n’est pas une vraie contradiction, juste une conséquence qui défie l’intuition de tous les jours.' },

  { id: 'laplace', icon: 'atom', field: 'physik', title: 'Le démon de Laplace', wiki: 'Démon de Laplace',
    text: 'Imagine une intelligence qui connaît, à un instant donné, la position et la vitesse de chaque particule de l’univers, ainsi que toutes les lois de la nature. Rien ne serait incertain pour elle. Elle pourrait calculer tout l’avenir et tout le passé.',
    q: 'L’avenir est-il donc déjà fixé ?',
    opts: ['Oui, tout est fixé', 'Non, il existe un vrai hasard', 'Fixé peut-être, mais jamais calculable'],
    args: [['Pour', 'Si chaque événement a une cause, l’état suivant découle nécessairement de l’état présent. Tes décisions aussi ne seraient alors que des processus dans le cerveau.'],
      ['Contre', 'La physique quantique connaît un vrai hasard : le moment où un atome se désintègre est imprévisible par principe. Et dans beaucoup de systèmes, la moindre erreur de mesure grossit comme une avalanche (le chaos).']],
    info: 'Pierre-Simon de Laplace a décrit cette idée en 1814. Elle résume la vision du monde de la physique classique et est au cœur de la question de savoir si le libre arbitre peut exister.' },

  { id: 'galilei', icon: 'key', field: 'physik', title: 'Les pierres de Galilée', wiki: 'Chute libre (physique)',
    text: 'Pendant près de 2 000 ans, on a suivi Aristote : les objets lourds tombent plus vite que les légers. Galilée s’est demandé : que se passe-t-il si l’on attache une pierre lourde et une légère avec une ficelle et qu’on les lâche ? (Sans résistance de l’air.)',
    q: 'Comment tombe la paire par rapport à la pierre lourde seule ?',
    opts: ['Plus vite, elle est plus lourde', 'Plus lentement, la légère la freine', 'Exactement aussi vite'],
    correct: 2,
    args: [['La contradiction', 'Selon Aristote, la pierre légère devrait freiner la lourde, donc la paire tomberait plus lentement. Mais la paire est aussi plus lourde que la pierre lourde seule, donc elle devrait tomber plus vite. Les deux ne peuvent pas être vrais.'],
      ['La solution', 'La contradiction ne disparaît que si tous les corps tombent à la même vitesse. Galilée y est arrivé par la seule réflexion, sans aucune expérience.']],
    info: 'L’argument figure dans les « Discorsi » de Galilée (1638). La plus belle preuve a été apportée en 1971 par l’astronaute David Scott sur la Lune : le marteau et la plume ont touché le sol au même instant.' },

  { id: 'aufzug', icon: 'key', field: 'physik', title: 'L’ascenseur d’Einstein', wiki: 'Principe d\'équivalence',
    text: 'Tu te réveilles dans une cabine sans fenêtre. Tu sens ton poids normal ; une balle que tu lâches tombe par terre. Deux possibilités : la cabine est posée sur Terre. Ou bien une fusée l’accélère régulièrement vers le haut dans l’espace vide.',
    q: 'Peux-tu savoir de l’intérieur laquelle est vraie ?',
    opts: ['Oui, avec une expérience astucieuse', 'Non, impossible de les distinguer'],
    correct: 1,
    args: [['L’explication', 'Aucune expérience dans la cabine ne peut montrer la différence. Sur place, la gravité et l’accélération agissent exactement de la même façon. C’est le principe d’équivalence.'],
      ['La conséquence', 'Dans la cabine accélérée, un rayon lumineux suivrait une trajectoire légèrement courbe. La gravité doit donc elle aussi courber la lumière. Cela a été confirmé en 1919 lors d’une éclipse de Soleil.']],
    info: 'Einstein a qualifié cette idée de 1907 de « pensée la plus heureuse de ma vie ». Il en a tiré, en huit ans, la relativité générale, où la gravité est une courbure de l’espace-temps.' },

  { id: 'olbers', icon: 'key', field: 'physik', title: 'Pourquoi la nuit est-elle noire ?', wiki: 'Paradoxe d\'Olbers',
    text: 'Suppose que l’univers soit infiniment grand, infiniment vieux et partout rempli d’étoiles de façon uniforme. Alors, dans chaque direction, ton regard finirait par tomber sur une étoile. Tout le ciel devrait briller aussi fort que la surface du Soleil.',
    q: 'Pourquoi fait-il quand même noir la nuit ?',
    opts: ['La poussière absorbe la lumière', 'L’univers a eu un commencement', 'Les étoiles sont simplement trop loin'],
    correct: 1,
    args: [['La solution', 'L’univers a environ 13,8 milliards d’années. Nous ne voyons que les étoiles dont la lumière a eu le temps de nous parvenir. En plus, l’espace s’étend et étire la lumière des galaxies lointaines jusque dans l’invisible.'],
      ['Pourquoi la poussière n’aide pas', 'Une poussière qui absorberait la lumière pour toujours s’échaufferait et finirait par briller aussi fort que les étoiles elles-mêmes.']],
    info: 'L’énigme porte le nom du médecin et astronome brêmois Heinrich Wilhelm Olbers (1823). Le simple fait qu’il fasse noir la nuit est donc un indice du Big Bang.' },

  { id: 'fermi', icon: 'loop', field: 'physik', title: 'Le paradoxe de Fermi', wiki: 'Paradoxe de Fermi',
    text: 'Notre galaxie compte à elle seule des centaines de milliards d’étoiles, beaucoup avec des planètes et des milliards d’années de plus que le Soleil. Une civilisation qui s’étendrait même lentement aurait pu coloniser toute la Voie lactée depuis longtemps. Pourtant, nous ne voyons et n’entendons rien.',
    q: 'Où sont-ils donc tous ?',
    opts: ['Ils n’existent pas, nous sommes seuls', 'Ils existent, mais trop loin', 'Les civilisations s’autodétruisent avant de voyager', 'Ils sont là et ne se montrent pas'],
    args: [['Le « Grand Filtre »', 'Une des étapes entre la matière inerte et le voyage interstellaire doit être extrêmement improbable. Si elle est derrière nous (l’apparition de la vie, par exemple), nous avons eu de la chance. Si elle est devant nous, ce n’est pas une bonne nouvelle.'],
      ['Des réponses sobres', 'L’espace est d’une immensité inimaginable, les voyages durent des dizaines de milliers d’années, et nous n’écoutons que depuis quelques décennies. Pour l’instant, le silence ne prouve pas grand-chose.']],
    info: 'Le physicien Enrico Fermi aurait demandé en 1950, au cours d’un déjeuner : « Mais où sont-ils tous ? » À ce jour, il n’existe aucune réponse admise.' },

  { id: 'grossvater', icon: 'loop', field: 'physik', title: 'Le paradoxe du grand-père', wiki: 'Paradoxe temporel',
    text: 'Tu voyages dans le passé avec une machine à remonter le temps et tu empêches ton grand-père de rencontrer ta grand-mère. Alors ton père ne naît jamais – et toi non plus. Mais alors, qui a voyagé dans le passé ?',
    q: 'Qu’en conclure ?',
    opts: ['Voyager dans le passé est impossible', 'On peut voyager, mais sans rien changer', 'Une nouvelle ligne temporelle apparaît'],
    args: [['Rien ne peut changer', 'Selon le principe d’autocohérence, seul ce qui colle à l’histoire connue peut se produire. Ta tentative échoue, peut-être justement de la manière qui provoque leur rencontre.'],
      ['Les mondes multiples', 'Tu atterris dans une autre branche de la réalité. Là, tu ne nais jamais, mais ta propre origine reste intacte.']],
    info: 'Le paradoxe vient de la science-fiction des années 1930 et 1940. La physique n’exclut pas clairement le voyage dans le passé ; Stephen Hawking soupçonnait toutefois que la nature l’empêche par principe.' },

  // ---------------- Logique et mathématiques ----------------
  { id: 'ziege', icon: 'key', field: 'logik', title: 'Le problème de Monty Hall', wiki: 'Problème de Monty Hall',
    text: 'Dans un jeu télévisé, il y a trois portes. Derrière l’une se trouve une voiture, derrière chacune des deux autres une chèvre. Tu choisis la porte 1. Le présentateur, qui sait où est la voiture, ouvre la porte 3 : une chèvre. Puis il te propose de changer pour la porte 2.',
    q: 'Faut-il changer ?',
    opts: ['Oui, changer', 'Non, garder la porte 1', 'Peu importe, c’est 50/50'],
    correct: 0,
    args: [['Les maths', 'Ton premier choix est bon avec une probabilité de 1/3. Ouvrir une porte à chèvre n’y change rien. Les 2/3 restants reposent maintenant entièrement sur l’autre porte. Changer double donc tes chances.'],
      ['Pour que ça fasse tilt', 'Imagine 100 portes. Tu en choisis une, le présentateur ouvre 98 portes à chèvre et en laisse exactement une fermée. Garderais-tu encore la tienne ?']],
    info: 'L’énigme est devenue célèbre en 1990 grâce à la chroniqueuse Marilyn vos Savant. Elle a donné la bonne réponse et reçu environ 10 000 lettres de protestation, dont beaucoup de mathématiciens qui avaient tort.' },

  { id: 'geburtstag', icon: 'key', field: 'logik', title: 'Le paradoxe des anniversaires', wiki: 'Paradoxe des anniversaires',
    text: 'À une fête, les invités sont réunis au hasard. Tu te demandes : combien de personnes faut-il dans la pièce pour qu’il y ait plus de 50 % de chances que deux d’entre elles aient leur anniversaire le même jour ?',
    q: 'Combien d’invités faut-il ?',
    opts: ['23', '57', '183', '366'],
    correct: 0,
    args: [['L’explication', 'La question n’est pas que quelqu’un ait le même anniversaire que toi, mais que deux personnes quelconques partagent le leur. Avec 23 personnes, il y a déjà 253 paires possibles. Cela suffit pour 50,7 %.'],
      ['Encore plus surprenant', 'Avec 57 invités, la probabilité dépasse déjà 99 %. Ce n’est que pour « quelqu’un a le même anniversaire que moi » qu’il faudrait 253 personnes.']],
    info: 'Le paradoxe des anniversaires n’est pas une vraie contradiction ; il montre juste à quel point notre intuition des probabilités est mauvaise. En cryptographie, « l’attaque des anniversaires » exploite précisément cet effet.' },

  { id: 'hilbert', icon: 'key', field: 'logik', title: 'L’hôtel de Hilbert', wiki: 'Hôtel de Hilbert',
    text: 'Un hôtel a une infinité de chambres : numéro 1, 2, 3, et ainsi de suite à l’infini. Toutes les chambres sont occupées. Tard dans la nuit, un nouveau client se présente à la réception et demande une chambre.',
    q: 'En obtient-il une ?',
    opts: ['Oui', 'Non, complet, c’est complet'],
    correct: 0,
    args: [['Comment ça marche', 'Chaque client passe à la chambre suivante : de 1 à 2, de 2 à 3, et ainsi de suite. Comme il n’y a pas de dernière chambre, tout le monde trouve une place et la chambre 1 se libère.'],
      ['Ce que ça montre', 'Avec les ensembles infinis, « complet » ne veut plus dire ce dont on a l’habitude. L’infini plus un est exactement aussi grand que l’infini.']],
    twist: { text: 'Maintenant, un car rempli d’une infinité de nouveaux clients s’arrête devant l’hôtel complet.',
      q: 'Trouvent-ils tous de la place, eux aussi ?', opts: ['Oui', 'Non, c’est trop'],
      note: 'Oui. Chaque client s’installe dans la chambre au numéro double : de 1 à 2, de 2 à 4, de 3 à 6. Ensuite, toutes les chambres impaires sont libres, et il y en a une infinité.' },
    info: 'David Hilbert a raconté cet exemple dans une conférence en 1924 pour illustrer la théorie de l’infini de Georg Cantor. Cantor a aussi montré qu’il existe des infinis de tailles différentes.' },

  { id: 'achilles', icon: 'key', field: 'logik', title: 'Achille et la tortue', wiki: 'Paradoxes de Zénon',
    text: 'Le rapide Achille fait la course avec une tortue et lui laisse de l’avance. Quand il atteint son point de départ, elle a un peu avancé. Quand il arrive là, elle est de nouveau un peu plus loin. Et ainsi de suite, une infinité de fois.',
    q: 'Achille finit-il par la rattraper ?',
    opts: ['Oui, évidemment', 'Non, il s’en approche toujours plus, c’est tout'],
    correct: 0,
    args: [['L’astuce', 'Zénon découpe une distance finie en une infinité de morceaux. Il en conclut implicitement qu’une infinité d’étapes prendrait un temps infini.'],
      ['La solution', 'Les morceaux sont de plus en plus courts, et leur somme est finie. Si Achille met 10 secondes pour le premier, 1 pour le suivant, puis 0,1 – le total fait à peine plus de 11 secondes.']],
    info: 'Zénon d’Élée a imaginé ce paradoxe vers 450 av. J.-C. pour montrer que le mouvement est une illusion. Il n’a pu être résolu proprement que plus de 2 000 ans plus tard, avec la notion de limite.' },

  { id: 'luegner', icon: 'loop', field: 'logik', title: 'Le paradoxe du menteur', wiki: 'Paradoxe du menteur',
    text: 'Prends cette seule phrase : « Cette phrase est fausse. » Si elle est vraie, ce qu’elle dit est exact – donc elle est fausse. Si elle est fausse, ce qu’elle dit est inexact – donc elle est vraie.',
    q: 'Qu’est-ce que cette phrase ?',
    opts: ['Vraie', 'Fausse', 'Ni vraie ni fausse', 'Les deux à la fois'],
    args: [['Ni l’un ni l’autre', 'Toute phrase qui ressemble à une affirmation n’affirme pas forcément quelque chose. Une phrase qui ne parle que de sa propre vérité flotte dans le vide.'],
      ['La solution stricte', 'Le logicien Alfred Tarski a séparé des niveaux de langage : une phrase n’a pas le droit de juger sa propre vérité. « Vrai » appartient à une langue située au-dessus de la langue.']],
    twist: { text: 'Dans un village, le barbier rase exactement les hommes qui ne se rasent pas eux-mêmes.',
      q: 'Le barbier se rase-t-il lui-même ?', opts: ['Oui', 'Non', 'Un tel barbier ne peut pas exister'],
      note: 'S’il se rase, il ne devrait pas ; s’il ne se rase pas, il devrait. Un tel barbier ne peut tout simplement pas exister. En 1901, Bertrand Russell a utilisé le même schéma pour montrer que la théorie des ensembles de l’époque était contradictoire.' },
    info: 'Le paradoxe est connu depuis l’Antiquité (Eubulide, IVe siècle av. J.-C.). En 1931, Kurt Gödel a fondé son théorème d’incomplétude sur une idée voisine : dans tout système d’arithmétique assez riche, il existe des énoncés vrais qu’on ne peut pas y démontrer.' },

  { id: 'haufen', icon: 'loop', field: 'logik', title: 'Le paradoxe du tas', wiki: 'Paradoxe sorite',
    text: 'Un million de grains de sable forment un tas. Si tu enlèves un seul grain, cela reste un tas – un grain ne fait pas de différence. C’est vrai à chaque étape. Au bout du compte, même un seul grain devrait donc encore être un tas.',
    q: 'Où est l’erreur ?',
    opts: ['Il y a une limite exacte, on ne la connaît juste pas', '« Tas » est flou, il n’y a pas de limite', 'À strictement parler, les tas n’existent pas'],
    args: [['Une limite nette', 'Peut-être que tout bascule vraiment à un grain précis. Que nous ne puissions pas montrer l’endroit ne veut pas dire qu’il n’existe pas.'],
      ['Les notions floues', 'Des mots comme « tas », « grand » ou « chauve » ont des zones grises. Au milieu, l’énoncé n’est ni clairement vrai ni clairement faux, seulement en partie.']],
    info: 'L’énigme vient d’Eubulide de Milet (IVe siècle av. J.-C.) et s’appelle aussi le paradoxe sorite. Elle se cache dans bien des débats réels : à partir de quand est-on adulte, pauvre ou malade ?' },

  { id: 'affen', icon: 'key', field: 'logik', title: 'Le singe et la machine à écrire', wiki: 'Paradoxe du singe savant',
    text: 'Un singe tape sur les touches d’une machine à écrire de façon totalement aléatoire. Il ne se fatigue jamais et dispose d’un temps infini.',
    q: 'Finira-t-il par taper « Hamlet » en entier ?',
    opts: ['Oui, c’est certain', 'Non, ça n’arrivera jamais'],
    correct: 0,
    args: [['Les mathématiques', 'Chaque suite de caractères a une chance minuscule mais fixe. Avec une infinité d’essais, elle apparaît un jour avec une probabilité de 1 – et même une infinité de fois.'],
      ['La réalité', 'Même pour une seule phrase, le singe aurait besoin en moyenne d’un temps inimaginablement plus long que l’âge de l’univers. « Infini », c’est tout simplement bien plus que « très longtemps ».']],
    info: 'L’idée remonte au mathématicien français Émile Borel (1913). En 2003, on a donné un clavier à de vrais singes dans leur enclos : ils ont tapé cinq pages, presque uniquement la lettre S, et ont cassé le clavier.' },

  { id: 'hinrichtung', icon: 'loop', field: 'logik', title: 'La pendaison inattendue', wiki: 'Paradoxe de l\'interrogation surprise',
    text: 'Un juge déclare : « Tu seras exécuté à midi un jour de semaine, la semaine prochaine, et ce sera une surprise. » Le prisonnier raisonne : vendredi est exclu, sinon je le saurais dès jeudi soir. Alors jeudi tombe aussi, puis mercredi – ça ne peut donc pas arriver du tout. Mercredi, le bourreau arrive. Surprise totale.',
    q: 'Où est la faille dans le raisonnement ?',
    opts: ['Dès le vendredi', 'Seulement aux jours d’avant', 'L’annonce se contredit elle-même'],
    args: [['Dès le vendredi', 'Le prisonnier suppose que l’annonce est vraie. Dès qu’il conclut que ça ne peut pas arriver, il n’y croit plus – et peut donc de nouveau être surpris.'],
      ['Savoir ce qu’on saura', 'L’énigme porte sur ce qu’on peut savoir de son propre savoir futur. Ce genre d’autoréférence est aussi traître que dans la phrase du menteur.']],
    info: 'Le paradoxe est apparu dans les années 1940. À ce jour, il n’existe aucune solution sur laquelle les logiciens s’accordent – seulement une centaine d’articles scientifiques aux propositions différentes.' },

  { id: 'dornroeschen', icon: 'loop', field: 'logik', title: 'Le problème de la Belle au bois dormant', wiki: 'Problème de la Belle au bois dormant',
    text: 'La Belle au bois dormant est endormie le dimanche. Puis on lance une pièce. Si c’est face, on ne la réveille que le lundi. Si c’est pile, on la réveille le lundi et le mardi, mais on efface sa mémoire entre les deux. Elle se réveille et ne sait pas quel jour on est.',
    q: 'De son point de vue, quelle est la probabilité que la pièce soit tombée sur face ?',
    opts: ['1/2', '1/3'],
    args: [['Pour 1/2', 'La pièce est équilibrée, et en se réveillant, la Belle n’apprend rien de nouveau. Elle savait d’avance qu’elle se réveillerait.'],
      ['Pour 1/3', 'Si l’on répète l’expérience souvent, deux tiers de tous les réveils tombent sur « pile ». Qui devrait parier à chaque réveil aurait intérêt à miser sur pile.']],
    info: 'Le problème a été popularisé en 2000 par le philosophe Adam Elga. Les spécialistes restent divisés entre « demistes » et « tiersistes » – les deux camps ont de bons arguments.' },

  // ---------------- Décisions et théorie des jeux ----------------
  { id: 'gefangene', icon: 'dice', field: 'wahl', title: 'Le dilemme du prisonnier', wiki: 'Dilemme du prisonnier',
    text: 'Ton complice et toi êtes dans des cellules séparées. Si vous vous taisez tous les deux, chacun prend 1 an. Si toi seul le dénonces, tu es libre et il prend 10 ans – et inversement. Si vous vous dénoncez mutuellement, chacun prend 5 ans. Vous ne pouvez pas vous concerter.',
    q: 'Que fais-tu ?',
    opts: ['Je me tais', 'Je le dénonce'],
    args: [['Trahir est « logique »', 'Quoi que fasse l’autre, dénoncer est mieux pour toi. S’il se tait, tu es libre au lieu de faire 1 an. S’il te dénonce, tu prends 5 ans au lieu de 10.'],
      ['Et pourtant pire', 'Si les deux raisonnent ainsi, chacun prend 5 ans au lieu de 1 an seulement s’ils s’étaient tus. Une conduite raisonnable de chacun mène au pire résultat pour tous.']],
    twist: { text: 'Tu ne joues pas une seule fois, mais cent fois de suite, et chacun voit ce que l’autre a fait la fois précédente.',
      q: 'Est-ce que cela change ta stratégie ?', opts: ['Oui, maintenant coopérer paie', 'Non, je ne change rien'],
      note: 'Lors de tournois entre programmes, une stratégie très simple a gagné : « donnant-donnant ». D’abord être aimable, puis toujours faire ce que l’autre a fait au tour précédent. La répétition rend la confiance possible.' },
    info: 'Le jeu a été mis au point à la RAND Corporation en 1950. Il explique la course aux armements, les guerres de prix et pourquoi la protection du climat est si difficile : chacun s’en sort mieux si ce sont les autres qui font l’effort.' },

  { id: 'newcomb', icon: 'dice', field: 'wahl', title: 'Le paradoxe de Newcomb', wiki: 'Paradoxe de Newcomb',
    text: 'Deux boîtes sont devant toi. La transparente contient 1 000 euros. La seconde est fermée. Un être qui prédit presque toujours correctement les décisions l’a remplie hier : avec un million s’il a prévu que tu ne prendrais que la boîte fermée – et avec rien s’il a prévu que tu prendrais les deux.',
    q: 'Que prends-tu ?',
    opts: ['Seulement la boîte fermée', 'Les deux boîtes'],
    args: [['Une seule', 'Presque tous ceux qui n’ont pris que la boîte fermée sont millionnaires. Presque tous ceux qui ont pris les deux sont repartis avec 1 000 euros. Pas besoin d’en savoir plus.'],
      ['Les deux', 'L’argent est déjà dedans ou il ne l’est pas. Ton choix ne peut pas changer le passé. Avec les deux boîtes, tu as dans tous les cas 1 000 euros de plus.']],
    info: 'Le physicien William Newcomb a imaginé le problème ; le philosophe Robert Nozick l’a fait connaître en 1969. Il écrivait : presque tout le monde trouve la réponse évidente – seulement, chacun une réponse différente.' },

  { id: 'buridan', icon: 'dice', field: 'wahl', title: 'L’âne de Buridan', wiki: 'Paradoxe de l\'âne de Buridan',
    text: 'Un âne affamé se tient exactement à mi-chemin entre deux bottes de foin. Elles sont aussi grosses, aussi proches et aussi appétissantes l’une que l’autre. Il n’y a pas la moindre raison de préférer l’une à l’autre.',
    q: 'Qu’arrive-t-il à un âne parfaitement rationnel ?',
    opts: ['Il meurt de faim – pas de raison, pas de choix', 'Il en prend une, tout simplement'],
    args: [['Il meurt de faim', 'Qui n’agit que pour des raisons a besoin d’une raison d’aller à gauche ou à droite. S’il n’y en a pas, il ne bouge pas. Ce serait la conséquence d’une volonté strictement calculable.'],
      ['Il choisit', 'Mourir de faim est pire que n’importe quelle botte de foin. Le choix rationnel est donc de tirer au hasard. Un bon décideur sait quand ruminer coûte plus cher que choisir.']],
    info: 'La parabole porte le nom du philosophe français Jean Buridan (XIVe siècle), mais ne figure nulle part dans ses écrits. L’idée se trouve déjà chez Aristote. Les ingénieurs connaissent le problème avec les circuits numériques qui restent bloqués entre 0 et 1.' },

  { id: 'pascal', icon: 'dice', field: 'wahl', title: 'Le pari de Pascal', wiki: 'Pari de Pascal',
    text: 'Soit Dieu existe, soit non ; on ne peut prouver ni l’un ni l’autre. Si tu crois et qu’il existe, tu gagnes le bonheur éternel. Si tu crois et qu’il n’existe pas, tu perds peu. Si tu ne crois pas et qu’il existe, tu perds tout.',
    q: 'Est-il donc rationnel de parier sur Dieu ?',
    opts: ['Oui, le calcul est juste', 'Non, la foi ne marche pas comme ça'],
    args: [['Pour', 'Un gain infini l’emporte sur n’importe quelle mise finie, même si la chance est minuscule. Qui calcule doit parier.'],
      ['Contre', 'Quel dieu ? Il existe de nombreuses religions qui s’excluent mutuellement. En plus, on ne peut pas croire sur commande, et un dieu ne récompenserait guère une piété calculée.']],
    info: 'Blaise Pascal a noté le pari dans ses « Pensées », publiées en 1670 après sa mort. On le considère comme l’une des premières applications de la théorie de la décision – à une question pour laquelle elle n’est peut-être pas faite.' },

  { id: 'allmende', icon: 'dice', field: 'wahl', title: 'La tragédie des biens communs', wiki: 'Tragédie des biens communs',
    text: 'Dix paysans se partagent le pré communal du village. Chacun se dit : si j’y mets une vache de plus, le profit est pour moi seul. Les dégâts de l’herbe broutée se répartissent sur les dix.',
    q: 'Que devient le pré à la longue ?',
    opts: ['Il est brouté jusqu’à la terre', 'Les paysans s’entendent à temps', 'Il faut l’État ou des clôtures'],
    args: [['La vision sombre', 'Pour chacun, la vache de plus est toujours rentable. Alors tout le monde ajoute des vaches jusqu’à ce que le pré soit ruiné. La liberté dans un bien commun mène tout le monde à la ruine.'],
      ['Le contre-exemple', 'La chercheuse Elinor Ostrom a trouvé partout dans le monde des villages qui préservent ensemble depuis des siècles forêts, zones de pêche et eau – avec leurs propres règles, leurs contrôles et leurs sanctions.']],
    info: 'Le biologiste Garrett Hardin a forgé l’expression en 1968. Elinor Ostrom a reçu en 2009 le prix Nobel d’économie, première femme à l’obtenir, pour avoir montré que la tragédie n’est pas inévitable. Le schéma s’applique à la surpêche et au climat.' },

  { id: 'ultimatum', icon: 'dice', field: 'wahl', title: 'Le jeu de l’ultimatum', wiki: 'Jeu de l\'ultimatum',
    text: 'Un inconnu reçoit 100 euros et doit t’en proposer une part. Si tu acceptes, l’argent est partagé ainsi. Si tu refuses, personne n’a rien. Il n’y a qu’un seul tour, et vous ne vous reverrez jamais. Il te propose 10 euros et en garde 90.',
    q: 'Tu acceptes ?',
    opts: ['Oui, 10 euros, c’est mieux que rien', 'Non, c’est scandaleux'],
    args: [['Accepter', 'Mathématiquement, tout montant au-dessus de zéro est un gain. Refuser te coûte 10 euros et ne te rapporte rien.'],
      ['Refuser', 'Les gens sont prêts à payer pour punir l’injustice. Justement parce que tout le monde le sait, la plupart des proposants offrent spontanément près de la moitié.']],
    info: 'L’expérience vient de l’économiste allemand Werner Güth (1982). Partout dans le monde, les offres en dessous d’environ 20 à 30 % sont très souvent refusées. Elle est devenue un témoin clé contre l’image de l’être humain purement égoïste.' },

  { id: 'petersburg', icon: 'dice', field: 'wahl', title: 'Le jeu de Saint-Pétersbourg', wiki: 'Paradoxe de Saint-Pétersbourg',
    text: 'On lance une pièce jusqu’à ce que face sorte pour la première fois. Si ça arrive dès le premier lancer, tu gagnes 2 euros. Au deuxième 4 euros, au troisième 8, et ça continue de doubler. Mathématiquement, le gain moyen est infiniment grand.',
    q: 'Combien paierais-tu pour jouer une fois ?',
    opts: ['20 euros au maximum', 'Quelques centaines d’euros', 'Tout ce que je possède'],
    args: [['Le calcul', 'Chaque étape ajoute exactement 1 euro à la moyenne : une chance sur deux de gagner 2, une sur quatre de gagner 4, et ainsi de suite. Une infinité d’étapes donne l’infini.'],
      ['Pourquoi presque personne ne paie cher quand même', 'Le deuxième million rend moins heureux que le premier. En plus, dans la moitié des parties, on ne gagne que 2 euros, et aucune banque ne pourrait jamais verser les gains géants.']],
    info: 'Nicolas Bernoulli a posé le problème en 1713 ; son cousin Daniel l’a résolu à Saint-Pétersbourg en 1738 avec l’idée d’utilité : ce qui compte, c’est ce que l’argent vaut pour toi, pas le montant. L’économie moderne repose sur cette idée.' },

  // ---------------- Connaissance et réalité ----------------
  { id: 'tank', icon: 'cube', field: 'wissen', title: 'Le cerveau dans une cuve', wiki: 'Cerveau dans une cuve',
    text: 'Imagine qu’un scientifique t’ait retiré le cerveau et l’ait plongé dans une solution nutritive. Par des câbles, un ordinateur lui envoie exactement les signaux qui viendraient sinon des yeux, des oreilles et de la peau. Tout ce que tu vois et ressens en ce moment serait simulé.',
    q: 'Peux-tu savoir avec certitude que ce n’est pas le cas ?',
    opts: ['Non, je ne peux pas le prouver', 'Oui, on peut l’exclure'],
    args: [['Non', 'Tous les tests que tu peux imaginer donneraient le même résultat dans la cuve. L’expérience ne peut pas prouver qu’il existe un monde derrière l’expérience.'],
      ['Oui', 'Le philosophe Hilary Putnam a fait valoir qu’un cerveau dans une cuve n’a jamais vu de vraies cuves. Ses mots « cerveau » et « cuve » ne désignent que des images du programme. La phrase « Je suis un cerveau dans une cuve » serait donc toujours fausse.']],
    info: 'La version moderne vient de Hilary Putnam (1981). C’est le remake du malin génie de René Descartes (1641) – et le modèle du film « Matrix ».' },

  { id: 'hoehle', icon: 'cube', field: 'wissen', title: 'L’allégorie de la caverne', wiki: 'Allégorie de la caverne',
    text: 'Des gens sont enchaînés dans une caverne depuis leur naissance et ne voient que la paroi devant eux. Derrière eux brûle un feu, et l’on fait passer des objets. Ils prennent les ombres sur la paroi pour toute la réalité. L’un d’eux est libéré, remonte et voit le Soleil.',
    q: 'Il revient et leur raconte. Que se passe-t-il ?',
    opts: ['Ils le croient et veulent sortir', 'Ils se moquent de lui', 'Ils se mettent en colère et s’en prennent à lui'],
    args: [['La réponse de Platon', 'Dans l’obscurité, celui qui revient voit moins bien que les autres et semble perdu. Ils se moquent de lui, et celui qui tenterait de les libérer, ils le tueraient volontiers.'],
      ['Ce que ça veut dire', 'Les ombres représentent ce que nous percevons par nos sens et tenons pour acquis. La connaissance est une montée pénible, et celui qui en parle aux autres se rend impopulaire.']],
    info: 'L’allégorie figure au livre VII de « La République » de Platon. Elle fait allusion au sort de son maître Socrate, que les Athéniens ont condamné à mort en 399 av. J.-C.' },

  { id: 'simulation', icon: 'cube', field: 'wissen', title: 'L’hypothèse de la simulation', wiki: 'Hypothèse de simulation',
    text: 'Suppose qu’une civilisation avancée ait assez de puissance de calcul pour simuler des mondes entiers avec des habitants conscients. Elle en ferait sans doute tourner un très grand nombre. Il y aurait alors bien plus d’esprits simulés que d’esprits réels.',
    q: 'Quelle est la probabilité que nous vivions dans une simulation ?',
    opts: ['Très probable', 'Possible, mais peu probable', 'Exclu', 'Ça ne change rien pour nous'],
    args: [['Le trilemme de Bostrom', 'L’une de ces trois affirmations doit être vraie : presque aucune civilisation n’atteint ce niveau. Ou presque aucune ne veut de telles simulations. Ou nous sommes presque certainement dans l’une d’elles.'],
      ['Les objections', 'Personne ne sait si la conscience peut seulement être simulée. Et une thèse que rien ne permet de tester n’explique, au fond, rien du tout.']],
    info: 'Le philosophe suédois Nick Bostrom a publié l’argument en 2003. C’est la version technique d’une très vieille question, déjà posée par la caverne de Platon et le malin génie de Descartes.' },

  { id: 'erlebnis', icon: 'cube', field: 'wissen', title: 'La machine à expériences', wiki: 'Machine à expérience',
    text: 'Des chercheurs ont construit une machine qui te fait vivre toutes les expériences que tu souhaites. Tu es allongé dans une cuve et tu vis une vie parfaitement heureuse, faite de succès, d’amour et d’aventures. Tout paraît réel, et tu oublies que tu es branché.',
    q: 'Tu te branches pour de bon ?',
    opts: ['Oui, le bonheur, c’est le bonheur', 'Non, je veux la vraie vie'],
    args: [['Se brancher', 'Au bout du compte, ce qui compte, c’est le ressenti de la vie. Si tu ne remarques jamais la différence, tu ne perds rien. Beaucoup de gens passent déjà des heures dans des mondes inventés.'],
      ['Ne pas se brancher', 'Nous voulons vraiment faire des choses, pas seulement avoir l’impression de les faire. Nous voulons être quelqu’un et vivre avec de vraies personnes. Il n’y a donc pas que les états agréables qui comptent.']],
    info: 'Robert Nozick a posé la question dans « Anarchie, État et utopie » (1974). Elle vise l’hédonisme, l’idée que seuls le plaisir et le bien-être comptent dans la vie.' },

  { id: 'molyneux', icon: 'key', field: 'wissen', title: 'Le problème de Molyneux', wiki: 'Problème de Molyneux',
    text: 'Une personne est aveugle de naissance. Elle a appris à distinguer une sphère d’un cube au toucher. Elle est opérée et peut soudain voir. Une sphère et un cube sont posés sur la table devant elle.',
    q: 'Reconnaît-elle la sphère rien qu’en la regardant ?',
    opts: ['Oui, tout de suite', 'Non, elle doit d’abord l’apprendre'],
    correct: 1,
    args: [['L’ancienne hypothèse', 'John Locke pensait que non. Ce que nous voyons et ce que nous touchons forment d’abord deux mondes séparés. Seule l’expérience les relie.'],
      ['Le résultat', 'En 2011, des enfants nés aveugles en Inde ont été opérés et testés juste après. Ils n’arrivaient pas à associer ce qu’ils voyaient à ce qu’ils avaient touché – mais l’ont appris en quelques jours.']],
    info: 'L’Irlandais William Molyneux, dont la femme était devenue aveugle, a posé la question en 1688 dans une lettre à John Locke. Pendant plus de 300 ans, on n’a pu que spéculer, jusqu’à ce que la médecine rende une expérience possible.' },

  { id: 'gettier', icon: 'cube', field: 'wissen', title: 'L’horloge arrêtée', wiki: 'Problème de Gettier',
    text: 'Tu regardes l’horloge de la gare : midi pile. Tu crois donc qu’il est midi. Et c’est le cas. Ce que tu ne sais pas : l’horloge s’est arrêtée hier à midi. Tu as regardé par hasard au bon moment.',
    q: 'Savais-tu qu’il était midi ?',
    opts: ['Oui, j’avais raison, non ?', 'Non, c’était juste de la chance'],
    args: [['Oui', 'Ta croyance était vraie, et tu avais une bonne raison : tu as regardé une horloge. On ne peut pas demander plus à un savoir.'],
      ['Non', 'Il n’y avait aucun vrai lien entre ta raison et la vérité. Une minute plus tard, tu te serais trompé avec la même assurance.']],
    info: 'Depuis Platon, on considérait le savoir comme une « croyance vraie justifiée ». En 1963, Edmund Gettier a montré avec des cas de ce genre, en trois pages à peine, que cela ne suffit pas. Ce qu’est exactement le savoir est de nouveau une question ouverte depuis.' },

  { id: 'teekanne', icon: 'cube', field: 'wissen', title: 'La théière de Russell', wiki: 'Théière de Russell',
    text: 'Quelqu’un affirme qu’entre la Terre et Mars, une petite théière en porcelaine tourne autour du Soleil. Elle est trop petite pour n’importe quel télescope. Tu ne peux pas prouver qu’elle n’existe pas.',
    q: 'Dois-tu pour autant tenir la théière pour possible ?',
    opts: ['Non, c’est à celui qui affirme d’apporter des preuves', 'Oui, tant qu’elle n’est pas réfutée'],
    args: [['Non', 'Sinon, il faudrait prendre au sérieux n’importe quelle affirmation qui échappe habilement à tout test. La charge de la preuve revient à celui qui affirme.'],
      ['L’objection', 'Absolument rien ne plaide pour une théière dans l’espace ; nous savons comment naissent les théières. Pour les grandes questions, la situation n’est pas aussi tranchée, alors la comparaison boite.']],
    info: 'Bertrand Russell a écrit cet exemple en 1952 dans un essai sur la question de l’existence de Dieu. Depuis, on le cite chaque fois que quelqu’un dit : « Prouve-moi donc que j’ai tort ! »' },
];
